import json
n=19
centers=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
g=[[0]*n for _ in range(n)]
for r,c,v in centers:
    g[r][c]=v
    for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
        g[rr][cc]=3
orig=[row[:] for row in g]
for i in range(n):
  for j in range(n):
    if orig[i][j]!=0: continue
    candidates=[]
    for r,c,v in centers:
      if i==r: candidates.append((abs(j-c),1,v)) # horizontal
      if j==c: candidates.append((abs(i-r),0,v)) # vertical wins equal via orientation 0
    if candidates:
      g[i][j]=min(candidates)[2]
assert len(g)==19 and all(len(row)==19 for row in g)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

