n=19
colored=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
hollow_centers=[(10,8)]
g=[[0]*n for _ in range(n)]
for r,c,v in colored:
 g[r][c]=v
 for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)): g[rr][cc]=3
for r,c in hollow_centers:
 for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)): g[rr][cc]=3
orig=[row[:] for row in g]
# Horizontal expansions omit the columns through blank-centered crosses; vertical expansions run through all rows.
blocked_cols={c for r,c in hollow_centers}
for r,c,v in colored:
 for j in range(n):
  if j not in blocked_cols and orig[r][j]==0: g[r][j]=v
for r,c,v in colored:
 for i in range(n):
  if orig[i][c]==0: g[i][c]=v
assert len(g)==19 and all(len(row)==19 for row in g)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

